Writing the error boundary component now.

## Tool: Write

```json
{
  "file_path": "/Users/user/ErrorBoundary.tsx",
  "content": "import { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('[ErrorBoundary]', error.message, {
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  retry = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      if (fallback) return fallback(error, this.retry);

      return (
        <div role="alert" style={{ padding: '1rem', border: '1px solid #f5a623', borderRadius: 4 }}>
          <strong>Something went wrong</strong>
          <pre style={{ fontSize: '0.85em', marginTop: '0.5rem', whiteSpace: 'pre-wrap' }}>
            {error.message}
          </pre>
          <button onClick={this.retry}>Retry</button>
        </div>
      );
    }

    return children;
  }
}
"
}
```

Done. Usage:

```tsx
// Default fallback UI
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary fallback={(error, retry) => (
  <div>
    <p>Oops: {error.message}</p>
    <button onClick={retry}>Try again</button>
  </div>
)}>
  <MyComponent />
</ErrorBoundary>
```

Key details:
- `getDerivedStateFromError` — captures error into state, triggers fallback render
- `componentDidCatch` — logs `error.message`, `stack`, and `componentStack` via `console.error`
- `retry` — resets state to `null`, re-renders children from scratch
- `fallback` prop — optional custom renderer; default fallback used if omitted
